<script setup lang="ts">
import { computed } from 'vue'
import { Close, Delete, ArrowUp, ArrowDown } from '@element-plus/icons-vue'
import { usePlayerStore } from '../store/player'
const props = defineProps<{ open:boolean }>(); const emit = defineEmits<{ close:[] }>(); const player=usePlayerStore(); let dragIndex=-1
const queue = computed(() => player.queue)
const fmt=(v?:number)=>v==null?'—':`${Math.floor(v/60)}:${String(Math.floor(v%60)).padStart(2,'0')}`
</script>
<template><aside v-if="props.open" class="player-drawer queue-panel" aria-label="播放队列"><header><div><span class="eyebrow">QUEUE</span><h3>播放队列 <small>{{queue.length}}</small></h3></div><button class="icon-button" aria-label="关闭队列" @click="emit('close')"><Close/></button></header><div v-if="!queue.length" class="drawer-empty">队列还是空的</div><ol v-else class="queue-list"><li v-for="(track,index) in queue" :key="String(track.id)" draggable="true" :class="{current:track.id===player.track?.id}" @dragstart="dragIndex=index" @dragover.prevent @drop="player.moveQueue(dragIndex,index)"><button class="queue-play" :aria-label="`播放 ${track.title}`" @click="player.play(track)"><img v-if="track.coverUrl" :src="track.coverUrl" alt=""/><span v-else>♪</span><b v-if="track.id===player.track?.id">{{player.playing?'▶':'Ⅱ'}}</b></button><button class="queue-title" @click="player.play(track)"><strong>{{track.title||'未命名作品'}}</strong><small>{{track.styleTags||'AI 音乐'}}</small></button><time>{{fmt(track.duration)}}</time><button class="queue-move" :disabled="index===0" aria-label="上移" @click="player.moveQueue(index,index-1)"><ArrowUp/></button><button class="queue-move" :disabled="index===queue.length-1" aria-label="下移" @click="player.moveQueue(index,index+1)"><ArrowDown/></button><button class="queue-move danger" aria-label="移除歌曲" @click="player.removeFromQueue(track.id)"><Delete/></button></li></ol><footer><button class="text-button" :disabled="!queue.length" @click="player.clearQueue();emit('close')">清空队列</button></footer></aside></template>
